#!/usr/bin/env python3
"""Audit the two-year observatory objective against current repository evidence."""

from __future__ import annotations

import json
from pathlib import Path

ANALYSIS = Path(__file__).resolve().parents[1] / "analysis" / "external-trend-intelligence"
OUTPUT = ANALYSIS / "goal-completion-audit.json"


def load(name: str) -> dict:
    return json.loads((ANALYSIS / name).read_text())


def main() -> int:
    progress = load("program-progress.json")
    health = load("release-health.json")
    qualification = load("candidate-qualification-matrix.json")
    history = load("refresh-history.json")
    ibis_review = load("ibis-claim-source-review.json")
    ibis_dispositions = load("ibis-claim-review-dispositions.json")
    financial_rights = load("financial-room-rights-review.json")
    record_quality = load("record-quality-audit.json")
    record_queue = load("record-quality-remediation-queue.json")
    host_audit = load("record-host-dependence-audit.json")
    host_queue = load("host-dependence-review-queue.json")
    open_gates = load("open-gate-register.json")
    domain_coverage = load("domain-coverage-audit.json")
    pipeline_steps = history["latest"].get("pipeline_step_count", "recorded")
    audit = {
        "schema": "external-trend-intelligence.goal-completion-audit.v1",
        "objective": "two-year external-first enterprise trend-intelligence observatory",
        "as_of": progress["as_of"],
        "overall_status": "in_progress_with_open_gates",
        "requirements": [
            {"id": "external_capture_refresh", "status": "partial", "evidence": ["TWO-YEAR-GOAL.md", "EXTERNAL-DATA-SOURCES.md", "source-family-registry.json", "refresh_external_observatory.py", "refresh-schedule-health.json", "refresh-status.json", "refresh-freshness-decision.json", "refresh-history.json", "refresh-continuity-audit.json", "continuity-coverage-plan.json", "open-gate-history.json", "domain-coverage-audit.json", "test_refresh_stale_gate.py", "test_external_refresh_workflow.py", "test_program_baseline_consistency.py", "program-scorecard.json"], "gap": f"The weekly schedule contract, stale gate, baseline consistency, recovery path, per-family freshness decisions, append-only gate workload history, explicit 104-week coverage plan, and required-domain coverage ({domain_coverage['observed_domain_count']}/{domain_coverage['required_domain_count']} domains observed) are exercised and refresh runs are recorded with {pipeline_steps}-step pass telemetry, but sustained unattended operation over the scheduled two-year cadence is not yet demonstrated."},
            {"id": "lineage_rights_units_periods_uncertainty", "status": "partial", "evidence": ["external-family-lineage-review.json", "rights-review-queue.json", "rights-assignment-queue.json", "RIGHTS-REVIEW-REQUEST.md", "rights-evidence-register.json", "rights-review-readiness.json", "food-insecurity-rights-review.json", "financial-room-rights-review.json", "mobility-access-rights-review.json", "uncertainty-coverage-audit.json", "external-acquisition-rights-review.json", "candidate-lineage-dependency-review.json", "candidate-independence-adjudication-queue.json", "ibis-claim-dependency-review.json", "ibis-claim-independence-audit.json", "ibis-claim-independence-review-queue.json", "ibis-first-review-batch.json", "ibis-claim-review-dispositions.json", "ibis-force-claim-review.json", "shed-emergency-expense-uncertainty-audit.json", "shed-point-estimate-reproduction-audit.json", "record-quality-audit.json", "record-quality-remediation-queue.json", "test_rights_release_gate.py", "observation-manifest.json"], "gap": f"Rights and publisher dependence remain unverified for all source families; the rights-assignment queue and rights-review-readiness artifact now make the eight-family ownership and sign-off prerequisites explicit, and the rights review request turns those prerequisites into a fillable human handoff. The candidate independence adjudication queue makes all five candidate reviews assignable with {load('candidate-independence-adjudication-queue.json')['high_priority_count']} high-priority rows. Candidate-specific reviews cover the monitored food-security lane, the mobility comparison, and {financial_rights['source_count']} financial-room sources. Record metadata quality is now audited across {record_quality['record_count']} records, with remediation status {record_queue['status']}; this makes source identity, lineage locator, period, unit, geography, uncertainty, counter-signal, and retrieval hash testable rather than implicit. The uncertainty coverage audit makes source-level, incomplete, and pending uncertainty visible across six decision-facing artifacts. The {ibis_review['sample_industry_count']}-industry IBIS sample and six-force review expose repeated source IDs, URLs, missing claim periods, and metadata gaps for dependency review; the claim-independence audit mechanically flags reused URLs, hosts, and publishers, the review queue turns the remaining low-dependency claims into assigned work, the first ten-claim packet is now fully triaged with {ibis_dispositions['completed_disposition_count']} conservative held dispositions and {ibis_dispositions['pending_first_batch_count']} pending rows, rather than unsupported promotion. Upstream redistribution and enterprise rights approval remain open. The SHED point estimate has only a non-release naive interval and design-based variance remains open."},
            {"id": "independent_source_comparison", "status": "partial", "evidence": ["independent-stage-comparison.json", "food-insecurity-independent-comparison.json", "mobility-access-independent-comparison.json", "room-independent-comparison.json", "room-independent-result.json", "us-financial-room-independent-comparison.json", "financial-room-decision-card.json", "compatible-measure-search.json", "global-growth-forecast-comparison.json", "shed-emergency-expense-2013-2025.json", "bounded-subset-lineage-review.json", "census-repair-proxy-comparison.json", "record-host-dependence-audit.json", "host-dependence-review-queue.json"], "gap": f"The compatibility scan now finds 209 cross-host measure groups and the release includes bounded food-insecurity, mobility-access, OECD/UN DESA/World Bank, and a same-publisher CBP-versus-NES repair measurement comparison. The financial-room decision card consolidates Australia and U.S. source-family evidence but remains mechanism context because denominators and uncertainty are not harmonized. Host dependence is now explicit across {host_audit['unique_host_count']} hosts, including {host_audit['shared_host_count']} shared hosts and {host_queue['high_priority_count']} high-priority review rows, but publisher independence is not thereby established. Distinct-publisher comparisons remain non-comparable holdouts because populations, reference periods, uncertainty, weighting, and rights differ; the Census repair comparison explicitly cannot count as independent confirmation, and no common-unit observed holdout has passed."},
            {"id": "trend_qualification", "status": "open", "evidence": ["candidate-qualification-matrix.json", "trend-qualification-rubric.json", "trend-monitoring-status.json", "trend-monitoring-evaluation.json"], "gap": f"{qualification['qualified_external_trend_count']} qualified trends; {qualification['held_count']} candidates held. Monitoring evaluation records continue/hold state for all candidates, but no new comparable release has triggered a reversal or retirement decision."},
            {"id": "backtest_and_falsification", "status": "partial", "evidence": ["backtest-readiness.json", "backtest-comparability-review.json", "forecast-backtest-register.json", "forecast-outcome-eligibility.json", "food-insecurity-temporal-holdout.json", "mobility-access-temporal-holdout.json", "ibis-adult-day-outcome-review.json", "cell-phone-repair-outcome-acquisition-plan.json", "census-repair-industry-snapshot.json", "census-nonemployer-repair-snapshot.json", "temporal-holdout-design.json", "temporal-holdout-result.json", "shed-temporal-holdout.json", "usda-temporal-holdout.json"], "gap": "The food-insecurity candidate has a descriptive Urban 2019–2023 to 2024–2025 holdout and non-pooled USDA challenge; the mobility lane has a bounded ACS 2023→2024 holdout plus an independent NHTS directional challenge; and the IBIS adult-day-care lane has a dated CDC outcome series plus a CMS Medicaid rate comparison. The forecast eligibility audit now distinguishes periods still open from eligible outcomes missing, so no partial-year score is created. The cell-phone repair lane now has reproducible 2019–2023 paid-employee CBP and 2019–2024 nonemployer Census proxies, but neither is phone-specific and they cannot be pooled with policy or e-waste evidence. Causal validation, uncertainty harmonization, independent utilization outcomes, and holdouts for the other candidates remain open."},
            {"id": "decision_ready_frontend", "status": "partial", "evidence": ["board.html", "FRONTEND-INTEGRATION.md", "frontend-publication-registry.json", "observatory-chart-catalog.json", "candidate-qualification-matrix.json", "temporal-decision-narrative.json", "record-quality-audit.json", "host-dependence-review-queue.json", "open-gate-register.json", "review-calendar.json", "test_frontend_publication_contract.py"], "gap": f"Reader surface exposes the qualified external food-insecurity pattern, held candidates, metadata quality, host-dependence review queue, and {open_gates['gate_count']} consolidated open gates ({open_gates['critical_gate_count']} critical); the publication contract now verifies that every registered narrative and chart resolves to a manifest-listed artifact with required caveat metadata, but no validated company outcome is published."},
            {"id": "analyst_operating_model", "status": "partial", "evidence": ["ANALYST-OPERATING-MODEL.md", "REFRESH-RUNBOOK.md", "operating-handoff.json", "ownership-assignment-queue.json", "operating-ownership-readiness.json", "refresh-continuity-audit.json", "successor-run-evidence.json", "evidence-acquisition-plan.json"], "gap": "The handoff records six roles, a reconciled ownership-assignment queue, a reproducible read-only successor-validation artifact, and an explicit readiness evaluation separating control pass from human assignment; named human ownership, an independently signed successor run, and sustained weekly continuity are still outstanding."},
            {"id": "validated_company_pilots", "status": "open", "evidence": ["pilot-register.json", "pilot-readiness.json", "pilot-contract-intake.json", "pilot-activation-queue.json", "PILOT-ACTIVATION-REQUEST.md", "pilot-bridge-simulation.json", "PILOT-VALIDATION-PROTOCOL.md", "test_pilot_activation_request.py", "test_internal_bridge_gate.py", "test_external_only_boundary.py"], "gap": "The synthetic bridge simulation and the human pilot activation request now exercise aggregate matching, unmatched and missing-outcome visibility, falsifier, stop-rule, rights, privacy, and sign-off requirements without company data; the pilot activation queue sequences the missing approvals and confirms all three designs are still blocked. No real pilot is approved because a company decision contract, named rights owner, internal exposure definition, and privacy review are still required after external monitoring; the fail-closed bridge and external-only release gates are exercised."},
        ],
        "release_status": health["release_status"],
        "boundary": "This audit is a conservative program status report. It does not redefine the goal as complete because the control plane and frontend are operational.",
        "next_action": "Use open-gate-register.json and evidence-acquisition-plan.json to assign and close rights, host-dependence, independent-compatible-holdout, backtest, ownership, and continuity work; then re-run this audit before any internal bridge.",
    }
    OUTPUT.write_text(json.dumps(audit, indent=2) + "\n")
    print(f"wrote {OUTPUT} ({len(audit['requirements'])} requirements)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
